INSERT INTO m_permission (grouping, code, entity_name, action_name, can_maker_checker) SELECT 'report', 'READ_LoanApplicationReport', 'LoanApplicationReport', 'READ', false WHERE NOT EXISTS (SELECT 1 FROM m_permission WHERE code = 'READ_LoanApplicationReport');
INSERT INTO m_permission (grouping, code, entity_name, action_name, can_maker_checker) SELECT 'report', 'READ_KYCNaturalPerson', 'KYCNaturalPerson', 'READ', false WHERE NOT EXISTS (SELECT 1 FROM m_permission WHERE code = 'READ_KYCNaturalPerson');
INSERT INTO m_permission (grouping, code, entity_name, action_name, can_maker_checker) SELECT 'report', 'READ_KYCReport', 'KYCReport', 'READ', false WHERE NOT EXISTS (SELECT 1 FROM m_permission WHERE code = 'READ_KYCReport');
